package com.example.csvfixtures.batch;
import org.slf4j.LoggerFactory; import org.springframework.batch.core.BatchStatus; import org.springframework.batch.core.Job; import org.springframework.batch.core.JobExecution; import org.springframework.batch.core.JobParametersBuilder; import org.springframework.batch.core.launch.JobLauncher; import org.springframework.batch.core.repository.JobRepository; import org.springframework.stereotype.Service;
@Service public class ImportService {
    private final CsvInput input; private final JobLauncher launcher; private final JobRepository repository; private final Job job;
    public ImportService(CsvInput input, JobLauncher launcher, JobRepository repository, Job job) { this.input = input; this.launcher = launcher; this.repository = repository; this.job = job; }
    public JobExecution run(String file, String sourceEventId) throws Exception { var path = input.validate(file); var hash = CsvInput.checksum(path); var event = sourceEventId == null ? "csv-sha256-" + hash : sourceEventId; var parameters = new JobParametersBuilder().addString("sourceEventId", event).addString("file", path.toString(), false).addString("checksum", hash, false).toJobParameters(); var previous = repository.getLastJobExecution(job.getName(), parameters); if (previous != null && previous.getStatus() == BatchStatus.COMPLETED) { LoggerFactory.getLogger(getClass()).info("event=fixtures_import_already_completed sourceEventId={}", event); return previous; } var execution = launcher.run(job, parameters); if (execution.getStatus() != BatchStatus.COMPLETED) throw new IllegalStateException("FIXTURES job " + execution.getId() + " ended " + execution.getStatus()); LoggerFactory.getLogger(getClass()).info("event=fixtures_import_completed sourceEventId={} executionId={}", event, execution.getId()); return execution; }
}
